 void menu(){HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING|MF_DISABLED,0,lastStatus.c_str());AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING,1,paused?L"Продолжить":L"Пауза");AppendMenuW(menu,MF_STRING,2,hidden?L"Показать эффекты":L"Скрыть эффекты");AppendMenuW(menu,MF_STRING,3,interactive?L"Выйти из игры":L"Поиграть со снегом");AppendMenuW(menu,MF_STRING,4,L"Растопить весь снег");AppendMenuW(menu,MF_STRING,5,L"Запустить уборщика");AppendMenuW(menu,MF_STRING|(anyTree()?MF_CHECKED:0),6,L"Показать Ёлочки");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING,7,L"Настройки…");AppendMenuW(menu,MF_STRING,8,L"Завершить Снег");POINT p;GetCursorPos(&p);SetForegroundWindow(tray);int result=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_RIGHTBUTTON,p.x,p.y,0,tray,nullptr);DestroyMenu(menu);PostMessageW(tray,WM_NULL,0,0);switch(result){case 1:togglePause();break;case 2:toggleHidden();break;case 3:if(interactive)exitGame();else enterGame();break;case 4:clearSnow();break;case 5:runCleaner();break;case 6:growTree(!anyTree());break;case 7:showSettings();break;case 8:DestroyWindow(tray);break;}}
